CREATE TABLE IF NOT EXISTS framework_areas (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,description TEXT NOT NULL,engine VARCHAR(64) NOT NULL,level INT NOT NULL DEFAULT 3,coverage INT NOT NULL DEFAULT 0,status VARCHAR(24) NOT NULL DEFAULT 'draft',content_need INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_framework_engine(engine),INDEX idx_framework_level(level),INDEX idx_framework_status(status));
